from pydantic import BaseModel, Field, GetCoreSchemaHandler
from pydantic_core import core_schema

from pydantic_cli import run_and_exit


class CastAbleEnum(Enum):
    """Example enum mixin that will cast enum from case-insensitive name"""

    @classmethod
    def __get_pydantic_core_schema__(
        cls, source_type: Any, handler: GetCoreSchemaHandler
    ) -> core_schema.CoreSchema:
        # Map the (case-insensitive) name to the enum value first, then let
        # the standard enum validation convert that value to the enum member.
        return core_schema.no_info_before_validator_function(
            cls.validate, handler(source_type)
        )

    @classmethod
    def validate(cls, v):
        if not isinstance(v, str):
            return v
        try:
            lookup = {k.lower(): item.value for k, item in cls.__members__.items()}
            return lookup[v.lower()]
        except KeyError:
            raise ValueError(f"Invalid value {v}. {cls.cli_help()}")

